const stages=[
['Research interest','Find the question behind your curiosity.','Choose a topic you care about, then narrow it to a specific group, setting, and issue. A manageable question is more useful than an enormous theme.','Which experience or observation makes you want to know more?','Write three interests. Pick one and name the people, place, and issue you want to understand.'],
['Research problem','Turn an observation into a researchable problem.','Describe what is happening, why it matters, and what remains unclear. Separate evidence of a problem from your assumptions about its cause.','What is the problem, who experiences it, and what evidence shows it matters?','Draft a paragraph with the context, problem, and consequence. Mark any claim that still needs evidence.'],
['Literature search','Find the conversation your research will join.','Break your topic into key concepts and synonyms. Combine concepts with AND and synonyms with OR. Record databases, search terms, and dates so your process is traceable.','What three concepts and alternative terms could help you find relevant studies?','Create a search string and a search log. Screen results using clear inclusion criteria.'],
['Literature analysis','Look for patterns across the evidence.','Read for the question, method, sample, findings, and limitations. Compare studies rather than summarizing one paper at a time. Use the literature matrix to keep evidence organized.','Where do the studies agree, disagree, or use different methods?','Compare three relevant papers in a matrix. Record the full citation and distinguish findings from your interpretation.'],
['Research gap','Identify what remains uncertain.','A useful gap is supported by the literature: an unresolved explanation, a conflicting finding, an underexamined context, or a methodological limitation. A topic being new to you does not establish a gap.','What is still unknown, and which studies demonstrate that uncertainty?','Write a gap statement supported by sources, then explain why addressing it would matter.'],
['Research questions','Ask something your study can answer.','Align your question with the problem and gap. Be specific about the phenomenon, population, and setting. Avoid causal wording unless your study design can support causal conclusions.','What focused question could you answer with realistically available evidence?','Draft one main question and up to three supporting questions. Check scope and feasibility.'],
['Objectives','Translate your question into a clear purpose.','Objectives describe what your study will accomplish. Use precise verbs such as describe, compare, explore, or estimate. Every objective should connect to a research question.','What will you describe, explore, or compare to answer your question?','Pair each research question with an objective and identify the evidence needed.'],
['Methodology','Choose a credible way to find out.','Select a design that fits your question. Explain participants or sources, sampling, data collection, analysis, limitations, and ethical safeguards. Confirm institutional requirements before collecting data.','What data do you need, how can you access it, and how will you analyze it?','Draft a methods plan. Include consent, privacy, feasibility, and any required ethics review.'],
['Research proposal','Connect your thinking into one coherent plan.','Bring your context, problem, literature, gap, questions, objectives, and methods together. Check that each part supports the next. Follow your institution’s format and citation requirements.','Can a reader follow the connection from your problem to your proposed method?','Use the proposal starter and readiness checklist. Ask a supervisor or peer to identify any missing links.']
];
let state={notes:[],completed:[]};let storageOk=true;
try{const raw=JSON.parse(localStorage.getItem('rrh-v1')||'null');if(raw&&Array.isArray(raw.notes)&&Array.isArray(raw.completed)){state.notes=raw.notes.filter(n=>n&&typeof n.title==='string'&&typeof n.body==='string'&&Number.isInteger(n.stage)&&n.stage>=0&&n.stage<9);state.completed=raw.completed.filter(n=>Number.isInteger(n)&&n>=0&&n<9)}}catch{storageOk=false}
const $=s=>document.querySelector(s);let active=0;
function persist(){try{localStorage.setItem('rrh-v1',JSON.stringify(state));storageOk=true;return true}catch{storageOk=false;$('#save-status').textContent='Browser storage is unavailable. Export your notebook to keep a copy.';return false}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function selectStage(i){active=i;document.querySelectorAll('.milestone').forEach((b,j)=>{b.classList.toggle('active',i===j);b.setAttribute('aria-pressed',i===j)});const s=stages[i];$('#stage-detail').innerHTML=`<p class="eyebrow">MILESTONE ${String(i+1).padStart(2,'0')} / 09</p><h3>${s[1]}</h3><p>${s[2]}</p><div class="prompt"><strong>PAUSE & REFLECT</strong><p>${s[3]}</p></div><div class="actions"><button class="button primary" id="write-stage">Capture your thinking ↗</button><button class="button ghost" id="complete-stage">${state.completed.includes(i)?'Completed ✓ · Undo':'Mark complete ✓'}</button></div>`;$('#write-stage').onclick=()=>{$('#note-stage').value=i;$('#note-title').value=s[0]+' reflection';$('#note-body').value=s[3]+'\n\n';$('#notebook').scrollIntoView({behavior:'smooth'});$('#note-body').focus({preventScroll:true})};$('#complete-stage').onclick=()=>{state.completed=state.completed.includes(i)?state.completed.filter(x=>x!==i):[...state.completed,i];persist();renderProgress();selectStage(i)};window.targetStage=i}
$('#milestones').innerHTML=stages.map((s,i)=>`<button class="milestone" aria-pressed="false"><span>${String(i+1).padStart(2,'0')}</span>${s[0]}</button>`).join('');document.querySelectorAll('.milestone').forEach((b,i)=>b.onclick=()=>selectStage(i));$('#note-stage').innerHTML=stages.map((s,i)=>`<option value="${i}">${s[0]}</option>`).join('');
function renderProgress(){$('#progress-label').textContent=`${state.completed.length} of 9 milestones completed`;$('#progress-bar').style.width=state.completed.length/9*100+'%'}
const lessonGroups=[['01','Find your direction','Interest, problem & literature search',0,3],['02','Connect the evidence','Analysis, gaps & research questions',3,6],['03','Build your proposal','Objectives, methods & proposal writing',6,9]];
$('#lessons').innerHTML=lessonGroups.map((l,i)=>`<button class="lesson" data-lesson="${i}"><span class="number">${l[0]}</span><h3>${l[1]}</h3><p>${l[2]}</p><small>3 practical lessons &nbsp; · &nbsp; Open module ↗</small></button>`).join('');
document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{const l=lessonGroups[+b.dataset.lesson];$('#lesson-content').innerHTML=`<p class="eyebrow">RESEARCH ACADEMY / MODULE ${l[0]}</p><h2>${l[1]}</h2>`+stages.slice(l[3],l[4]).map((s,i)=>`<h3>${l[3]+i+1}. ${s[0]}</h3><p>${s[2]}</p><p><strong>Try it:</strong> ${s[4]}</p>`).join('')+`<p><strong>Worked example:</strong> ${l[3]===0?'“Student wellbeing” is broad. Narrow it to how first-year students describe balancing paid work and study at one institution. Search for related studies before deciding what remains unknown.':l[3]===3?'If studies report different experiences of working students, compare their populations and methods before proposing a gap. Ask how first-year students in your setting describe those experiences; do not claim no research exists without a thorough search.':'For a question about experiences, a qualitative interview study may fit. Explain recruitment, consent, interview questions, and your analysis approach. Check feasibility and ethics requirements with your supervisor.'}</p><button class="button primary" id="module-go">Explore these milestones →</button>`;$('#lesson-dialog').showModal();$('#module-go').onclick=()=>{$('#lesson-dialog').close();selectStage(l[3]);$('#journey').scrollIntoView({behavior:'smooth'})}});$('.close').onclick=()=>$('#lesson-dialog').close();$('#lesson-dialog').addEventListener('click',e=>{if(e.target===$('#lesson-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
function download(name,text,type='text/markdown'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
const downloads={proposal:['research-proposal-starter.md','# Research proposal starter\n\nWorking title:\nAuthor:\nDate:\n\n'+['Background and context','Problem statement','Literature synthesis','Evidence-supported research gap','Research questions','Objectives','Conceptual or theoretical framework','Methodology: design, sampling, collection, analysis','Ethics, consent, and data management','Scope and limitations','Timeline and resources','References'].map(s=>'## '+s+'\n\n[Draft this section. Support factual claims with verified sources.]\n').join('\n')+'\nAdapt this outline to your institution and supervisor requirements.'],matrix:['literature-review-matrix.csv','Citation,DOI or URL,Research question,Context and sample,Design and methods,Key findings,Limitations,Relevance to my study,Notes\r\n'],framework:['conceptual-framework-guide.md','# Conceptual framework guide\n\n1. State your research question.\n2. Define the key concepts using relevant scholarship.\n3. Identify proposed relationships and explain the evidence behind each.\n4. Sketch the concepts and labeled connections.\n5. State assumptions, boundaries, and alternative explanations.\n6. Explain how the framework informs collection and analysis.\n\nA conceptual relationship is not proof of causation. Distinguish a framework you develop from an established theory, and cite its sources.\n'],checklist:['proposal-readiness-checklist.md','# Proposal readiness checklist\n\n'+['The problem is specific and supported by evidence','The review synthesizes relevant sources','The gap is justified, not merely asserted','Questions align with objectives','Methods can answer the questions','Data access and timeline are feasible','Ethics, consent, privacy, and required review are addressed','Limitations are acknowledged','Claims and references have been checked','The proposal follows institutional requirements','A supervisor or peer has reviewed the draft'].map(s=>'- [ ] '+s).join('\n')]};document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>{const d=downloads[b.dataset.download];download(d[0],d[1],b.dataset.download==='matrix'?'text/csv':'text/markdown')});
function renderNotes(){$('#notes').innerHTML=state.notes.length?state.notes.map((n,i)=>`<article class="note"><button data-delete="${i}" aria-label="Delete idea ${esc(n.title)}">Delete</button><small>${stages[n.stage][0]}</small><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p></article>`).join(''):'<div class="empty"><h3>Your next discovery starts here.</h3><p>Save an idea, a question, or a connection.<br>Your notes will appear in this space.</p></div>';document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('Delete this idea from your notebook?')){state.notes.splice(+b.dataset.delete,1);persist();renderNotes()}})}
$('#note-form').onsubmit=e=>{e.preventDefault();const title=$('#note-title').value.trim(),body=$('#note-body').value.trim();if(!title||!body){$('#save-status').textContent='Add a title and some thinking before saving.';return}state.notes.unshift({title,body,stage:+$('#note-stage').value,created:new Date().toISOString()});const saved=persist();renderNotes();$('#note-title').value='';$('#note-body').value='';$('#save-status').textContent=saved?'Idea saved on this device. Export a copy to keep it elsewhere.':'Idea kept for this session only. Export your notebook to keep it.'};$('#export').onclick=()=>download('my-research-notebook.md','# My research notebook\n\n'+state.notes.map(n=>`## ${n.title}\nMilestone: ${stages[n.stage][0]}\n\n${n.body}\n`).join('\n---\n\n')+'\n## Completed milestones\n'+state.completed.map(i=>'- '+stages[i][0]).join('\n'));
selectStage(0);renderProgress();renderNotes();if(!storageOk)$('#save-status').textContent='Browser storage is unavailable. Export your notes before leaving.';
const obs=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}),{rootMargin:'-15% 0px -55% 0px'});document.querySelectorAll('section[id]').forEach(e=>obs.observe(e));
