const canvas=$('#cosmos'),ctx=canvas.getContext('2d');const reduced=matchMedia('(prefers-reduced-motion: reduce)');let paused=reduced.matches,angle=0,last=0,mx=0,my=0;const points=Array.from({length:360},(_,i)=>{const y=1-(i/359)*2,r=Math.sqrt(1-y*y),a=i*Math.PI*(3-Math.sqrt(5));return{x:Math.cos(a)*r,y,z:Math.sin(a)*r}});const links=[];points.forEach((a,i)=>points.slice(i+1).forEach((b,j)=>{if(Math.hypot(a.x-b.x,a.y-b.y,a.z-b.z)<.24)links.push([i,i+j+1])}));const orbitStages=[0,2,4,8];$('#orbit-labels').innerHTML=orbitStages.map(i=>`<button class="orbit" data-stage="${i}">${String(i+1).padStart(2,'0')} &nbsp; ${stages[i][0]} ↗</button>`).join('');document.querySelectorAll('.orbit').forEach(b=>b.onclick=()=>{selectStage(+b.dataset.stage);$('#journey').scrollIntoView({behavior:reduced.matches?'auto':'smooth'})});const motion=$('#motion');function setMotion(){motion.textContent=paused?'Resume motion':'Pause motion';motion.setAttribute('aria-pressed',paused)}setMotion();motion.onclick=()=>{paused=!paused;setMotion()};reduced.addEventListener('change',e=>{paused=e.matches;setMotion()});$('#universe').addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();mx=(e.clientX-r.left)/r.width-.5;my=(e.clientY-r.top)/r.height-.5});$('#universe').addEventListener('pointerleave',()=>{mx=0;my=0});
function frame(t){requestAnimationFrame(frame);if(document.hidden||t-last<32)return;last=t;const rect=canvas.getBoundingClientRect(),w=rect.width,h=rect.height,dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);if(!paused)angle+=.0025;const a=angle+(paused?0:mx*.15)+(window.targetStage||0)*.03,r=Math.min(w*.34,h*.35),cx=w*.54,cy=h*.47;function project(p){const x=p.x*Math.cos(a)+p.z*Math.sin(a),z=-p.x*Math.sin(a)+p.z*Math.cos(a);const tilt=.22+(paused?0:my*.08),y=p.y*Math.cos(tilt)-z*Math.sin(tilt),zz=p.y*Math.sin(tilt)+z*Math.cos(tilt);const scale=3.5/(3.5+zz);return{x:cx+x*r*scale,y:cy+y*r*scale,z:zz,s:scale}}const pp=points.map(project);const glow=ctx.createRadialGradient(cx,cy,0,cx,cy,r*1.55);glow.addColorStop(0,'#326a7122');glow.addColorStop(.65,'#3baaa912');glow.addColorStop(1,'#07121d00');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);links.forEach(([i,j])=>{const p=pp[i],q=pp[j];ctx.strokeStyle=`rgba(112,219,207,${.06+(1-p.z)*.11})`;ctx.lineWidth=.6;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke()});pp.forEach((p,i)=>{ctx.fillStyle=i%17===0?'#d7ffe9':`rgba(137,230,219,${.2+(1-p.z)*.3})`;ctx.beginPath();ctx.arc(p.x,p.y,(i%17===0?2.4:1.1)*p.s,0,Math.PI*2);ctx.fill()});ctx.save();ctx.translate(cx,cy);ctx.rotate(-.35);ctx.strokeStyle='#7faeaa35';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(0,0,r*1.4,r*.42,0,0,Math.PI*2);ctx.stroke();ctx.rotate(.85);ctx.strokeStyle='#75a3c02b';ctx.beginPath();ctx.ellipse(0,0,r*1.3,r*.65,0,0,Math.PI*2);ctx.stroke();ctx.restore();const positions=[[.53,.19],[.84,.40],[.27,.59],[.69,.73]];document.querySelectorAll('.orbit').forEach((el,i)=>{el.style.left=positions[i][0]*w+'px';el.style.top=positions[i][1]*h+'px'})}requestAnimationFrame(frame);
